const storage = require('./storage');
const t = require('./todos');

const USAGE = `Usage:
  node index.js add "<text>"
  node index.js list
  node index.js complete <id>
  node index.js delete <id>`;

/**
 * Run a command. Returns the exit code; output goes through the injected
 * streams so tests can capture it.
 */
function run(argv, { file, out = console.log, err = console.error } = {}) {
  const [command, ...args] = argv;
  try {
    switch (command) {
      case 'add': {
        if (args.length > 1) throw new t.UsageError('Quote multi-word text: add "<text>"');
        const r = t.addTodo(storage.load(file), args[0]);
        storage.save(r.todos, file);
        out(`Added todo ${r.todo.id}: ${r.todo.text}`);
        return 0;
      }
      case 'list':
        out(t.formatList(storage.load(file)));
        return 0;
      case 'complete': {
        const r = t.completeTodo(storage.load(file), t.parseId(args[0]));
        storage.save(r.todos, file);
        out(`Completed todo ${r.todo.id}: ${r.todo.text}`);
        return 0;
      }
      case 'delete': {
        const r = t.deleteTodo(storage.load(file), t.parseId(args[0]));
        storage.save(r.todos, file);
        out(`Deleted todo ${r.todo.id}: ${r.todo.text}`);
        return 0;
      }
      default:
        if (command !== undefined) err(`Unknown command "${command}".`);
        err(USAGE);
        return 1;
    }
  } catch (e) {
    err(`Error: ${e.message}`);
    return 1;
  }
}

module.exports = { run, USAGE };
'use strict';
const fs = require('fs');
const path = require('path');

/** Resolve the todos file: $TODOS_FILE if set, else ./todos.json in the cwd. */
function defaultFile() {
  return process.env.TODOS_FILE || path.join(process.cwd(), 'todos.json');
}

/**
 * Load todos from disk. A missing file is an empty list; unreadable or
 * malformed content throws with the file path so the user can fix it.
 */
function load(file = defaultFile()) {
  let raw;
  try {
    raw = fs.readFileSync(file, 'utf8');
  } catch (err) {
    if (err.code === 'ENOENT') return [];
    throw new Error(`Cannot read ${file}: ${err.message}`);
  }
  if (raw.trim() === '') return [];
  let data;
  try {
    data = JSON.parse(raw);
  } catch (err) {
    throw new Error(`${file} is not valid JSON: ${err.message}`);
  }
  if (!Array.isArray(data)) throw new Error(`${file} must contain a JSON array`);
  return data;
}

/** Write todos atomically (temp file + rename) to avoid truncated data. */
function save(todos, file = defaultFile()) {
  const tmp = `${file}.${process.pid}.tmp`;
  try {
    fs.writeFileSync(tmp, JSON.stringify(todos, null, 2) + '\n');
    fs.renameSync(tmp, file);
  } catch (err) {
    fs.rmSync(tmp, { force: true });
    throw new Error(`Cannot write ${file}: ${err.message}`);
  }
}

module.exports = { load, save, defaultFile };
