/** Error for invalid user input; the CLI prints its message without a stack. */
class UsageError extends Error {}

/** Next id is max existing id + 1, so ids are never reused after a delete of a non-last item. */
function nextId(todos) {
  return todos.reduce((max, t) => Math.max(max, t.id), 0) + 1;
}

/** Return a new list with a todo appended. */
function addTodo(todos, text, now = new Date()) {
  const trimmed = typeof text === 'string' ? text.trim() : '';
  if (!trimmed) throw new UsageError('Todo text is required. Usage: add "<text>"');
  const todo = { id: nextId(todos), text: trimmed, completed: false, createdAt: now.toISOString() };
  return { todos: [...todos, todo], todo };
}

/** Parse a positive-integer id from CLI input. */
function parseId(value) {
  if (value === undefined || value === '') throw new UsageError('A todo id is required.');
  if (!/^\d+$/.test(String(value)) || Number(value) < 1 || !Number.isSafeInteger(Number(value))) {
    throw new UsageError(`Invalid id "${value}": must be a positive integer.`);
  }
  return Number(value);
